import pandas as pd
from datetime import datetime
import re

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw_payments = inputs["raw_payments"].copy()

    # Initialize reject list
    rejects = []
    survivors = []

    for idx, row in raw_payments.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        reject_reason = None

        # R1: MISSING_ID
        if reject_reason is None:
            if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ""):
                reject_reason = "MISSING_ID"

        # R2: BAD_AMOUNT
        if reject_reason is None:
            if pd.isna(amount_txt):
                reject_reason = "BAD_AMOUNT"
            else:
                amount_str = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
                # Legacy number pattern: optional +/-, one or more digits, optional .DD or .D
                if not re.match(r'^[+\-]?\d+(?:\.\d{1,2})?$', amount_str):
                    reject_reason = "BAD_AMOUNT"

        # R3: NON_POSITIVE
        if reject_reason is None:
            try:
                amount_str = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
                amount_val = float(amount_str)
                if amount_val <= 0:
                    reject_reason = "NON_POSITIVE"
            except (ValueError, AttributeError):
                reject_reason = "BAD_AMOUNT"

        # R4: BAD_CURRENCY
        if reject_reason is None:
            if pd.isna(currency):
                reject_reason = "BAD_CURRENCY"
            else:
                currency_upper = currency.strip().upper() if isinstance(currency, str) else str(currency).upper()
                if currency_upper not in ["USD", "EUR", "GBP"]:
                    reject_reason = "BAD_CURRENCY"

        # R5: BAD_DATE
        if reject_reason is None:
            if pd.isna(pay_date_txt):
                reject_reason = "BAD_DATE"
            else:
                date_str = pay_date_txt.strip() if isinstance(pay_date_txt, str) else str(pay_date_txt)
                # Check exact format YYYY-MM-DD
                if not re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
                    reject_reason = "BAD_DATE"
                else:
                    try:
                        parsed_date = datetime.strptime(date_str, "%Y-%m-%d").date()
                    except ValueError:
                        reject_reason = "BAD_DATE"

        if reject_reason is not None:
            rejects.append({"row_num": row_num, "reject_reason": reject_reason})
        else:
            # Survivor - passed R1-R5
            amount_str = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
            amount_val = float(amount_str)
            currency_upper = currency.strip().upper() if isinstance(currency, str) else str(currency).upper()
            date_str = pay_date_txt.strip() if isinstance(pay_date_txt, str) else str(pay_date_txt)
            parsed_date = datetime.strptime(date_str, "%Y-%m-%d").date()
            payment_id_trimmed = payment_id.strip() if isinstance(payment_id, str) else payment_id

            survivors.append({
                "row_num": row_num,
                "payment_id": payment_id_trimmed,
                "account_id": account_id,
                "amount": amount_val,
                "currency": currency_upper,
                "pay_date": parsed_date
            })

    # R6: DUPLICATE - among survivors, keep only the one with lowest row_num per payment_id
    if survivors:
        survivors_df = pd.DataFrame(survivors)
        # Group by payment_id and find the minimum row_num in each group
        min_row_num_per_id = survivors_df.groupby("payment_id", as_index=False)["row_num"].min()
        min_row_num_per_id.columns = ["payment_id", "min_row_num"]

        # Merge to identify which rows are duplicates
        survivors_df = survivors_df.merge(min_row_num_per_id, on="payment_id")

        # Rows where row_num != min_row_num are duplicates
        duplicates = survivors_df[survivors_df["row_num"] != survivors_df["min_row_num"]]
        for _, dup_row in duplicates.iterrows():
            rejects.append({"row_num": dup_row["row_num"], "reject_reason": "DUPLICATE"})

        # Keep only non-duplicates
        valid = survivors_df[survivors_df["row_num"] == survivors_df["min_row_num"]].copy()
        valid_payments = valid[["payment_id", "account_id", "amount", "currency", "pay_date"]].reset_index(drop=True)
    else:
        valid_payments = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    payment_rejects = pd.DataFrame(rejects)
    if payment_rejects.empty:
        payment_rejects = pd.DataFrame(columns=["row_num", "reject_reason"])

    return {
        "valid_payments": valid_payments,
        "payment_rejects": payment_rejects
    }
